     if (exchange_flags & EXCHANGE_FLAG_HAS_SECURED_EXT) {
         uint32_t secured_ext_len = 0;
         proto_tree_add_item_ret_uint(pl_tree, hf_payload_secured_ext_length, tvb, offset, 2, ENC_LITTLE_ENDIAN, &secured_ext_len);
